<div class="container"><header class="page-heading"><span class="eyebrow">MY TECHNOLOGY STACK</span><h1>The right tools.<br><span class="muted-heading">For the right reasons.</span></h1><p>A practical stack for complete web applications, from the data underneath to the interface your team uses every day.</p></header><section class="listing-section"><?php $tech=records('technologies');foreach(array_unique(array_column($tech,'group')) as $group):?><div class="stack-group"><h2><?=e($group)?></h2><div class="stack-grid"><?php foreach($tech as $t):if($t['group']!==$group)continue;?><article class="stack-card"><h3><?=e($t['title'])?></h3><p><?=e($t['description'])?></p></article><?php endforeach;?></div></div><?php endforeach;?></section></div><?php cta('Your requirements first.<br>The technology follows.');?>
